`)},level_2_vanishing_gradient:{level:2,title:"关卡 2：深层网络梯度消失与激活函数革命",badge:"反向连乘 / 梯度流诊断",desc:"在 5 层深层网络 [2, 6, 6, 6, 1] 中深入对比 Sigmoid 饱和导数连乘与 LeakyReLU 梯度传递，直观诊断浅层梯度消失现象。",defaultCode:["// =================================================================","// 关卡 2：深层网络梯度消失 (Vanishing Gradient) 与激活函数革命","// 核心目标：对比 5 层深层网络中 Sigmoid 导数饱和连乘 vs LeakyReLU 梯度传递","// =================================================================","",'print("🔬 [关卡 2] 构建 5 层深层网络拓扑 [2, 6, 6, 6, 1]...");',"const topology = [2, 6, 6, 6, 1];","","// 1. 构建全 Sigmoid 深层网络 vs LeakyReLU 深层网络",'const netSigmoid = new NeuralNetwork(topology, ["sigmoid", "sigmoid", "sigmoid", "sigmoid"], 0.1, "sgd", "mse");','const netReLU = new NeuralNetwork(topology, ["leaky_relu", "leaky_relu", "leaky_relu", "sigmoid"], 0.1, "sgd", "mse");',"","const sample = { input: [0.8, -0.6], target: [1.0] };","","// 计算单步解析反向传播",'const bwdSigmoid = netSigmoid.backward(sample.input, sample.target, "mse");','const bwdReLU = netReLU.backward(sample.input, sample.target, "mse");',"",'print("📉 [单步梯度流对比] 各层权重梯度范数 ||dW^(l)||:");','print("  • Sigmoid: 输入浅层 ||dW^(1)|| = " + bwdSigmoid.layerGradients[0].norm.toExponential(4) + " | 输出深层 ||dW^(4)|| = " + bwdSigmoid.layerGradients[3].norm.toExponential(4));','print("  • LeakyReLU: 输入浅层 ||dW^(1)|| = " + bwdReLU.layerGradients[0].norm.toExponential(4) + " | 输出深层 ||dW^(4)|| = " + bwdReLU.layerGradients[3].norm.toExponential(4));',"","// 2. 在双月牙数据集上迭代 400 轮，记录收敛对比",'const rawSamples = getDataset("moons", { count: 80, noise: 0.1 });',"const { train, test } = splitTrainTest(rawSamples, 0.8);","","const epochs = 400;","const sigmoidLosses = [];","const reluLosses = [];","","for (let ep = 1; ep <= epochs; ep++) {",'  const trSig = netSigmoid.trainEpoch(train, 0.1, "sgd", "mse");','  const trReLU = netReLU.trainEpoch(train, 0.1, "sgd", "mse");',"","  if (ep % 15 === 0 || ep === 1) {","    sigmoidLosses.push(trSig.loss);","    reluLosses.push(trReLU.loss);","  }","}","",'const evalSig = netSigmoid.evaluate(test, "mse");','const evalReLU = netReLU.evaluate(test, "mse");',"",'print("✅ [关卡 2 达成] 训练结束! 最终准确率: Sigmoid = " + evalSig.accuracy.toFixed(1) + "% | LeakyReLU = " + evalReLU.accuracy.toFixed(1) + "%");',"","// 绘制损失收敛轨迹对比","plotLoss({",'  title: "关卡 2: 5层网络收敛轨迹 (紫线: Sigmoid梯度衰减停滞 vs 绿线: LeakyReLU稳健收敛)",',"  trainLoss: sigmoidLosses,","  valLoss: reluLosses","});","","// 输出逐层梯度衰减对比表","displayTable({",'  title: "关卡 2: 5层深层网络各层梯度敏感度 ||dW^(l)|| 衰减对比",','  headers: ["网络层级", "Sigmoid 梯度范数", "LeakyReLU 梯度范数", "梯度倍率优势", "现象诊断"],',"  rows: bwdSigmoid.layerGradients.map((g, idx) => {","    const sNorm = g.norm;","    const rNorm = bwdReLU.layerGradients[idx].norm;","    const ratio = (rNorm / (sNorm + 1e-12)).toFixed(1);","    return [",'      "第 " + (idx + 1) + " 层 (" + (idx === 0 ? "输入浅层" : idx === 3 ? "输出深层" : "隐藏层") + ")",',"      sNorm.toExponential(4),","      rNorm.toExponential(4),",'      ratio + "x",','      sNorm < 1e-4 ? "⚠️ 发生梯度消失 (停滞)" : "✅ 梯度健康传导"',"    ];","  })","});"].join(`
`)},level_3_optimizers:{level:3,title:"关卡 3：优化器进化史与收敛竞赛",badge:"SGD vs Momentum vs RMSprop vs Adam",desc:"在相同初值拓扑下让四大优化器同台竞技，记录多维收敛速度、峡谷震荡平抑与最终精度排行。",defaultCode:["// =================================================================","// 关卡 3：优化器进化史与收敛竞赛 (SGD vs Momentum vs RMSprop vs Adam)","// 核心目标：在相同初值拓扑下对比四大优化器的收敛速度与稳定性","// =================================================================","",'print("🏁 [关卡 3] 初始化四大优化器同台竞速试验...");',"",'const dataset = getDataset("moons", { count: 100, noise: 0.1 });',"const { train, test } = splitTrainTest(dataset, 0.8);","",'const optimizers = ["sgd", "momentum", "rmsprop", "adam"];',"const netConfig = [2, 6, 4, 1];",'const actConfig = ["leaky_relu", "leaky_relu", "sigmoid"];',"","const networks = {",'  sgd: new NeuralNetwork(netConfig, actConfig, 0.08, "sgd", "mse"),','  momentum: new NeuralNetwork(netConfig, actConfig, 0.08, "momentum", "mse"),','  rmsprop: new NeuralNetwork(netConfig, actConfig, 0.08, "rmsprop", "mse"),','  adam: new NeuralNetwork(netConfig, actConfig, 0.08, "adam", "mse"),',"};","","const epochs = 300;","const lossHistories = { sgd: [], momentum: [], rmsprop: [], adam: [] };","","for (let ep = 1; ep <= epochs; ep++) {","  optimizers.forEach(opt => {",'    const tr = networks[opt].trainEpoch(train, 0.08, opt, "mse");',"    if (ep % 10 === 0 || ep === 1) {","      lossHistories[opt].push(tr.loss);","    }","  });","}","","// 汇总测试集评估指标","const summary = optimizers.map(opt => {",'  const ev = networks[opt].evaluate(test, "mse");',"  const initL = lossHistories[opt][0];","  const finalL = lossHistories[opt][lossHistories[opt].length - 1];","  const dropPct = (((initL - finalL) / initL) * 100).toFixed(1);","  return {","    opt: opt.toUpperCase(),","    finalLoss: finalL,","    accuracy: ev.accuracy,",'    drop: dropPct + "%"',"  };","});","",'print("🏆 [关卡 3 达成] 四大优化器竞速排行榜:");',"summary.forEach((s, i) => {",'  print("  第 " + (i + 1) + " 名: " + s.opt.padEnd(8) + " -> 最终损失: " + s.finalLoss.toFixed(5) + ", 验证准确率: " + s.accuracy.toFixed(1) + "% (降幅 " + s.drop + ")");',"});","","// 绘制 SGD (紫线) vs Adam (绿线) 损失曲线","plotLoss({",'  title: "关卡 3: 优化器收敛轨迹对比 (紫线: SGD 震荡迟缓 vs 绿线: Adam 快速自适应逼近)",',"  trainLoss: lossHistories.sgd,","  valLoss: lossHistories.adam","});","","// 渲染四大优化器详细评测表","displayTable({",'  title: "关卡 3: 四大优化器 300 轮训练效能综合对照",','  headers: ["优化器类型", "初始损失", "最终损失", "损失降幅", "测试准确率", "收敛特性评估"],',"  rows: summary.map((s, idx) => {","    const optKey = optimizers[idx];","    const initL = lossHistories[optKey][0].toFixed(5);","    const finalL = s.finalLoss.toFixed(5);","    const notes = optKey === 'adam'",'      ? "⭐ 一阶动量+二阶自适应学习率，收敛最快最稳"',"      : optKey === 'rmsprop'",'      ? "⚡ 梯度均方根归一化，自适应平抑陡峭维度震荡"',"      : optKey === 'momentum'",'      ? "💨 增加惯性动量，加速冲过平坦鞍点"','      : "🐢 传统梯度下降，在狭长峡谷中容易剧烈横向震荡";','    return [s.opt, initL, finalL, s.drop, s.accuracy.toFixed(1) + "%", notes];',"  })","});"].join(`
`)},level_4_learning_rate_uat:{level:4,title:"关卡 4：学习率临界效应与 UAT 波形拟合",badge:"UAT连续回归 / 拟合优度 R²",desc:"探究通用近似定理 (UAT)，使用连续隐藏层高保真逼近复合高频非线性波形，检验拟合优度 R² 与残差分布。",defaultCode:["// =================================================================","// 关卡 4：学习率 η 临界效应与连续非线性函数逼近 (UAT 通用近似定理)","// 核心目标：验证连续单隐藏层对复合高频波形 f(x) 的高精度回归逼近","// =================================================================","",'print("🌊 [关卡 4] 载入连续非线性复合波形数据集 f(x) = sin(2πx) + 0.3cos(4πx)...");','const waveData = getDataset("wave", { count: 80, noise: 0.03 });',"const { train, test } = splitTrainTest(waveData, 0.8);","",'print("📊 样本数: 训练 " + train.length + " 点 | 验证 " + test.length + " 点");',"","// 构建回归神经网络: [1 -> 10 -> 6 -> 1] (隐藏层 Tanh/LeakyReLU, 输出层 Linear)",'const net = new NeuralNetwork([1, 10, 6, 1], ["tanh", "leaky_relu", "linear"], 0.05, "adam", "mse");',"","const epochs = 800;",'print("🔄 开始回归拟合训练 (" + epochs + " 轮)...");',"","for (let ep = 1; ep <= epochs; ep++) {",'  const tr = net.trainEpoch(train, 0.05, "adam", "mse");',"  if (ep % 200 === 0 || ep === epochs) {",'    const val = net.evaluate(test, "mse");','    print("Epoch [" + ep + "/" + epochs + "] -> Train MSE: " + tr.loss.toFixed(6) + " | Val MSE: " + val.loss.toFixed(6));',"  }","}","","// 提取测试点绘制连续波形拟合曲线","const sortedSamples = [...waveData].sort((a, b) => a.input[0] - b.input[0]);","const xVals = [];","const yTrue = [];","const yPred = [];","","sortedSamples.forEach(s => {","  xVals.push(s.input[0]);","  yTrue.push(s.target[0]);","  const p = net.forward(s.input).output[0];","  yPred.push(p);","});","","// 计算决定系数 R²","const meanY = yTrue.reduce((a, b) => a + b, 0) / yTrue.length;","const ssTot = yTrue.reduce((acc, y) => acc + Math.pow(y - meanY, 2), 0);","const ssRes = yTrue.reduce((acc, y, idx) => acc + Math.pow(y - yPred[idx], 2), 0);","const r2Score = (1 - ssRes / (ssTot + 1e-8)).toFixed(4);","",'print("🏆 [关卡 4 达成] 回归拟合优度 R² = " + r2Score + " (越接近 1.0 表示通用近似拟合越完美)");',"","// 绘制真实目标曲线 vs 神经网络预测拟合曲线","plotRegression({",'  title: "关卡 4: 连续非线性波形回归拟合 (R² 拟合优度: " + r2Score + ")",',"  xValues: xVals,","  yTrue: yTrue,","  yPred: yPred","});","","// 输出测试集样本残差对照表","displayTable({",'  title: "关卡 4: 连续波形样本点预测与残差对照 (抽样 10 点)",','  headers: ["输入自变量 x", "真实函数值 f(x)", "网络回归预测 ŷ", "绝对残差 |y - ŷ|", "拟合评级"],',"  rows: sortedSamples.filter((_, i) => i % 8 === 0).map(s => {","    const p = net.forward(s.input).output[0];","    const diff = Math.abs(s.target[0] - p);","    return [","      s.input[0].toFixed(3),","      s.target[0].toFixed(4),","      p.toFixed(4),","      diff.toFixed(4),",'      diff < 0.05 ? "⭐ 极高精度" : diff < 0.12 ? "✅ 良好逼近" : "⚠️ 存在偏差"',"    ];","  })","});"].join(`
